using System.Windows;using LabMaster.Services;namespace LabMaster;public partial class QCWindow:Window{readonly QCService service=new();public QCWindow(){InitializeComponent();Loaded+=async(_,_)=>await LoadAsync();}async Task LoadAsync(){try{Grid.ItemsSource=await service.GetAsync();}catch(Exception ex){MessageBox.Show(ex.Message,"Lab Master",MessageBoxButton.OK,MessageBoxImage.Error);}}async void Add_Click(object s,RoutedEventArgs e){var w=new AddQCWindow{Owner=this};if(w.ShowDialog()==true)await LoadAsync();}}